  }
  function save(event: FormEvent) {
    event.preventDefault();
    const nextErrors: typeof errors = {};
    if ("'!profile.name.trim()) nextErrors.name = '"'Укажите ваше имя';
    if ("'!/''^[''^'"\\s@]+@["'^'"\\s@]+\\.["'^'"\\s@]+"'$/.test(profile.email.trim())) nextErrors.email = '"'Введите корректный email';
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) { document.getElementById(nextErrors.name ? 'name' : 'email')?.focus(); return; }
    const clean = { ...profile, name: profile.name.trim(), email: profile.email.trim() };
    try { localStorage.setItem('forma-profile', JSON.stringify(clean)); setSaved(clean); setProfile(clean); setToast('Настройки сохранены на этом устройстве'); }
    catch { setToast('Не удалось сохранить настройки. Проверьте доступ к хранилищу браузера.'); }
  }
  function cancel() {
    uploadVersion.current++; setUploading(false); setProfile(saved); setErrors({}); setFileError('');
    if (dirty) setToast('Изменения отменены');
  }

  const navigation: { id: string; title: string; icon: IconName }[] = [
    { id: 'personal', title: 'Мой профиль', icon: 'user' },
    { id: 'security', title: 'Безопасность', icon: 'shield' },
    { id: 'notifications', title: 'Уведомления', icon: 'bell' },
    { id: 'regional', title: 'Язык и регион', icon: 'globe' },
  ];

  return <div className=\"app-shell\">
    <aside className=\"sidebar\">
      <a className=\"brand\" href=\"#\" aria-label=\"Forma — настройки профиля\" onClick={() => goTo('personal')}><span className=\"brand-mark\"><i/><i/><i/></span>forma<span className=\"brand-dot\">.</span></a>
      <div className=\"workspace\"><span className=\"workspace-icon\">A<span>✦</span></span><div><strong>Личное пространство</strong><span>Ваш уютный уголок</span></div><span className=\"workspace-chevron\"><Icon name=\"chevron\" size={13}/></span></div>
      <div className=\"nav-label\">НАСТРОЙКИ АККАУНТА</div>
      <nav className=\"side-nav\" aria-label=\"Настройки аккаунта\">{navigation.map(item => <button key={item.id} className={active === item.id ? 'nav-item active' : 'nav-item'} onClick={() => goTo(item.id)} aria-current={active === item.id ? 'location' : undefined}><Icon name={item.icon}/><span>{item.title}</span>{active === item.id && <span className=\"active-dot\"/>}</button>)}</nav>
      <div className=\"sidebar-bottom\"><div className=\"help-card\"><span className=\"help-art\"><Icon name=\"help\" size={23}/><span className=\"spark spark-one\">✦</span><span className=\"spark spark-two\">✧</span></span><strong>Всё начинается с вас</strong><p>Настройте пространство так,<br/>чтобы вам было удобно.</p><button onClick={() => setHelp(true)}>Нужна помощь? <Icon name=\"arrow\" size={16}/></button></div>
      <div className=\"sidebar-account\"><Avatar profile={saved} small/><div><strong>{saved.name.split(' ')[0]}</strong><span>Личный аккаунт</span></div><span className=\"account-status\" title=\"Аккаунт активен\"/></div></div>
    </aside>

    <div className=\"main-shell\">
      <header className=\"topbar\"><div className=\"breadcrumbs\"><span>Аккаунт</span><Icon name=\"chevron\" size={12}/><span>Настройки профиля</span></div><div className=\"topbar-right\"><span className=\"private-badge\"><span/>Личное пространство</span><button className=\"icon-button help-button\" aria-label=\"Помощь\" onClick={() => setHelp(true)}><Icon name=\"help\"/></button><span className=\"topbar-divider\"/><Avatar profile={saved} small/></div></header>
      <main className=\"main-content\">
        <div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ АККАУНТ</div><h1>Настройки профиля<span className=\"heading-dot\">.</span></h1><p>Немного о вас. Всё — под вашим контролем.</p></div><span className=\"profile-label\"><Icon name=\"user\" size={15}/>Личный профиль</span></div>
        <form className=\"settings-card\" onSubmit={save} noValidate>
          <section id=\"personal\" className=\"settings-section personal-section\">
            <div className=\"section-heading\"><span className=\"section-icon\"><Icon name=\"user\" size={18}/></span><div><h2>Личная информация</h2><p>Так вас будут видеть в рабочем пространстве.</p></div></div>
            <div className=\"avatar-row\"><div className=\"avatar-wrapper\"><Avatar profile={profile}/><span className=\"avatar-online\"/></div><div className=\"avatar-actions\"><div className=\"avatar-buttons\"><Button size=\"m\" view=\"outlined\" className=\"upload-button\" onClick={() => fileRef.current?.click()} loading={uploading}><Icon name=\"upload\" size={15}/>Загрузить фото</Button><button type=\"button\" className=\"icon-button delete-avatar\" aria-label=\"Удалить фото\" disabled={"'!profile.avatar || uploading} onClick={() => { uploadVersion.current++; update('"'avatar', ''); setFileError(''); }}><Icon name=\"trash\" size={17}/></button></div><p>JPG, PNG или WebP. Не более 5 МБ.</p>{fileError && <span className=\"field-error\" role=\"alert\">{fileError}</span>}</div><input ref={fileRef} type=\"file\" accept=\"image/jpeg,image/png,image/webp\" onChange={upload} className=\"visually-hidden\" aria-label=\"Загрузить аватар\" tabIndex={-1}/></div>
            <div className=\"fields-grid\"><div className=\"field\"><label htmlFor=\"name\">Имя</label><TextInput id=\"name\" name=\"name\" size=\"l\" value={profile.name} onUpdate={v => update('name', v)} autoComplete=\"name\" validationState={errors.name ? 'invalid' : undefined} errorMessage={errors.name} placeholder=\"Ваше имя\" controlProps={{maxLength: 100}}/></div><div className=\"field\"><label htmlFor=\"email\">Email</label><TextInput id=\"email\" name=\"email\" size=\"l\" type=\"email\" value={profile.email} onUpdate={v => update('email', v)} autoComplete=\"email\" validationState={errors.email ? 'invalid' : undefined} errorMessage={errors.email} placeholder=\"you@example.com\" endContent={<span className=\"input-mail\"><Icon name=\"mail\" size={16}/></span>}/></div></div>
          </section>
          <section id=\"regional\" className=\"settings-section regional-section\"><div className=\"fields-grid\"><div className=\"field\"><label htmlFor=\"language\"><Icon name=\"globe\" size={15}/>Язык интерфейса</label><Select id=\"language\" size=\"l\" width=\"max\" value={[profile.language]} onUpdate={v => update('language', v[0])} options={languages} aria-label=\"Язык интерфейса\"/></div><div className=\"field\"><label htmlFor=\"timezone\"><span className=\"clock-icon\"/>Часовой пояс</label><Select id=\"timezone\" size=\"l\" width=\"max\" value={[profile.timezone]} onUpdate={v => update('timezone', v[0])} options={timezones} filterable filterPlaceholder=\"Найти город или часовой пояс\" aria-label=\"Часовой пояс\"/></div></div><p className=\"field-hint\">Используем для отображения времени и отправки уведомлений.</p></section>
          <section id=\"security\" className=\"settings-section security-section\"><div className=\"section-heading\"><span className=\"section-icon\"><Icon name=\"shield\" size={18}/></span><div><h2>Безопасность</h2><p>Дополнительная забота о вашем аккаунте.</p></div></div><div className={"'`security-option ${profile.twoFactor ? '"'enabled' : ''}"'`}><div><div className="option-title">Двухфакторная авторизация <span className="recommended">Рекомендуем</span></div><p>Дополнительное подтверждение при входе в аккаунт.</p></div><Switch size="l" checked={profile.twoFactor} onUpdate={v => update('"'twoFactor', v)} aria-label=\"Двухфакторная авторизация\"/></div></section>
          <section id=\"notifications\" className=\"settings-section notifications-section\"><div className=\"section-heading\"><span className=\"section-icon\"><Icon name=\"bell\" size={18}/></span><div><h2>Email-уведомления</h2><p>Выбирайте, какие письма вы хотите получать.</p></div><span className=\"notification-caption\">Только полезное, обещаем</span></div><div className=\"notification-list\">
            <Checkbox size=\"l\" checked={profile.product} onUpdate={v => update('product', v)}><span className=\"checkbox-copy\"><strong>Новости продукта</strong><span>Новые возможности, улучшения и важные обновления.</span></span></Checkbox>
            <Checkbox size=\"l\" checked={profile.alerts} onUpdate={v => update('alerts', v)}><span className=\"checkbox-copy\"><strong>Системные алерты</strong><span>Важные события и изменения в вашем аккаунте.</span></span></Checkbox>
            <Checkbox size=\"l\" checked={profile.digest} onUpdate={v => update('digest', v)}><span className=\"checkbox-copy\"><strong>Дайджест за неделю</strong><span>Главное за последние 7 дней в одном письме.</span></span></Checkbox>
          </div></section>
          <footer className=\"form-footer\"><span className={"'`save-note ${dirty ? '"'unsaved' : ''}"'`}><Icon name={dirty ? '"'user' : 'check'} size={15}/>{dirty ? 'Есть несохранённые изменения' : 'Всё актуально. Вы прекрасны.'}</span><div className=\"form-buttons\"><Button size=\"l\" view=\"outlined\" onClick={cancel}>Отмена</Button><Button size=\"l\" view=\"action\" type=\"submit\" disabled={uploading}><Icon name=\"check\" size={17}/>Сохранить</Button></div></footer>
        </form>
        <div className=\"privacy-note\"><Icon name=\"lock\" size={13}/><span>Ваши данные в безопасности и доступны только вам.</span></div>
        <div className=\"page-footer\"><span>© {new Date().getFullYear()} Forma</span><span>Пространство, в котором легко быть собой <span className=\"tiny-flower\">✳</span></span></div>
      </main>
    </div>
    {toast && <div className=\"toast\" role=\"status\"><span className=\"toast-icon\"><Icon name=\"check\" size={17}/></span>{toast}<button className=\"icon-button\" aria-label=\"Закрыть уведомление\" onClick={() => setToast('')}><Icon name=\"close\" size={16}/></button></div>}
    <dialog ref={helpRef} className=\"help-dialog\" onCancel={() => setHelp(false)} onClick={e => { if (e.target === e.currentTarget) setHelp(false); }}><button className=\"icon-button dialog-close\" aria-label=\"Закрыть помощь\" onClick={() => setHelp(false)}><Icon name=\"close\"/></button><span className=\"dialog-icon\"><Icon name=\"help\" size={26}/></span><h2>Пусть всё будет удобно</h2><p>Все настройки находятся на одной странице.</p><div className=\"help-content\"><strong>Как изменить фото?</strong><p>Нажмите «Загрузить фото» и выберите JPG, PNG или WebP до 5 МБ. Мы обрежем изображение по центру.</p><strong>Как сохранить изменения?</strong><p>Нажмите «Сохранить». Параметры сохраняются в этом браузере. Кнопка «Отмена» вернёт последние сохранённые настройки.</p><strong>Как работает безопасность?</strong><p>Здесь сохраняется предпочтение двухфакторной авторизации. Для реальной защиты входа потребуется подключение сервиса авторизации.</p></div><Button view=\"action\" size=\"l\" width=\"max\" onClick={() => setHelp(false)}>Всё понятно</Button></dialog>
  </div>;
}
EOF
