args.command:
/bin/bash -lc "cat >> src/styles.css <<'EOF'

/* A compact rhythm keeps the full form easy to scan on a laptop. */
@media (min-width: 561px) {
  .topbar { height: 66px; }
  .main-content { padding-top: 26px; }
  .page-heading { margin-bottom: 22px; }
  .eyebrow { line-height: 12px; margin-bottom: 7px; }
  .page-heading p { line-height: 17px; margin-top: 7px; }
  .settings-section { padding-top: 18px; padding-bottom: 18px; }
  .section-heading { margin-bottom: 15px; }
  .avatar { width: 58px; height: 58px; }
  .avatar-small { width: 32px; height: 32px; }
  .avatar-row { margin-bottom: 16px; }
  .field > label { font-size: 11px; line-height: 16px; margin-bottom: 7px; }
  .regional-section { padding-top: 17px; padding-bottom: 15px; }
  .field-hint { font-size: 10px; line-height: 14px; margin-top: 8px; }
  .section-heading p { font-size: 11px; }
  .notifications-section .section-heading { margin-bottom: 15px; }
  .notification-list { gap: 12px; }
  .checkbox-copy { gap: 3px; }
  .checkbox-copy strong { font-size: 12px; }
  .checkbox-copy > span { font-size: 10px; line-height: 1.4; }
  .form-footer { padding-top: 15px; padding-bottom: 15px; }
  .privacy-note { margin-top: 14px; }
  .page-footer { margin-top: 22px; padding-top: 16px; padding-bottom: 16px; }
}
.security-option { gap: 12px; }
.security-copy { margin-right: auto; }
.security-option .section-icon { background: #eaf0e1; }
.security-option .option-title { font-size: 12px; }
.security-option p { font-size: 10px; line-height: 1.5; }
.field .g-text-input__control, .field .g-select-control__option-text { font-size: 12px; }
.notifications-section .g-checkbox__icon { color: white; }
@media (max-width: 560px) {
  .security-option { padding: 14px 10px; gap: 9px; }
  .security-option .section-icon { display: none; }
  .security-option .option-title { font-size: 11px; }
  .security-option p { font-size: 9px; }
}
EOF
